BEGIN;
-- Dev only: all fixture documents, accounts and serials roll back.

DO $$
DECLARE cash_id uuid;cash_jv uuid;cash_value jsonb;cash_quote jsonb;target uuid;before_balance numeric;sgn numeric;actor uuid;c uuid;client uuid;inv uuid:=gen_random_uuid();supplier uuid:=gen_random_uuid();cost uuid;note uuid;j uuid;j2 uuid;v integer;serial text;q jsonb;r jsonb;blocked boolean;k text;t text;l campaign_lines%ROWTYPE;a campaign_influencers%ROWTYPE;
BEGIN
 SELECT p.id INTO actor FROM profiles p JOIN roles ro ON ro.id=p.role_id WHERE ro.slug='super_admin' AND p.is_active LIMIT 1;
 PERFORM set_config('request.jwt.claim.sub',actor::text,true);PERFORM set_config('request.jwt.claims',jsonb_build_object('sub',actor,'role','authenticated','aal','aal2')::text,true);
 SET LOCAL ROLE authenticated;
 c:=tw_accounting_create_company('QA Media posting rollback','EG','EGP','2026-01-01','[{"code":"100000","name":"Assets","parent":null,"type":"Asset","normal":"Debit","kind":"Group"},{"code":"110000","name":"Cash and banks","parent":"100000","type":"Asset","normal":"Debit","kind":"Group"},{"code":"111001","name":"Petty Cash","parent":"110000","type":"Asset","normal":"Debit","kind":"Posting"},{"code":"112001","name":"Main Operating Bank","parent":"110000","type":"Asset","normal":"Debit","kind":"Posting"},{"code":"112002","name":"Foreign Currency Bank","parent":"110000","type":"Asset","normal":"Debit","kind":"Posting"},{"code":"113001","name":"Transfers in Transit","parent":"110000","type":"Asset","normal":"Debit","kind":"Posting"},{"code":"120000","name":"Receivables","parent":"100000","type":"Asset","normal":"Debit","kind":"Group"},{"code":"121001","name":"Trade Accounts Receivable","parent":"120000","type":"Asset","normal":"Debit","kind":"Control","subledger":"Customer"},{"code":"122001","name":"Unbilled Revenue / Contract Assets","parent":"120000","type":"Asset","normal":"Debit","kind":"Control","subledger":"Customer"},{"code":"123001","name":"Allowance for Credit Losses","parent":"120000","type":"Asset","normal":"Credit","kind":"Posting"},{"code":"130000","name":"Advances and prepayments","parent":"100000","type":"Asset","normal":"Debit","kind":"Group"},{"code":"131001","name":"Supplier and Creator Advances","parent":"130000","type":"Asset","normal":"Debit","kind":"Control","subledger":"Supplier / creator"},{"code":"132001","name":"Staff Advances","parent":"130000","type":"Asset","normal":"Debit","kind":"Control","subledger":"Employee"},{"code":"133001","name":"Prepaid Expenses","parent":"130000","type":"Asset","normal":"Debit","kind":"Posting"},{"code":"134001","name":"Refundable Deposits","parent":"130000","type":"Asset","normal":"Debit","kind":"Posting"},{"code":"140000","name":"Recoverable taxes","parent":"100000","type":"Asset","normal":"Debit","kind":"Group"},{"code":"141001","name":"Recoverable Input VAT","parent":"140000","type":"Asset","normal":"Debit","kind":"Control","subledger":"Supplier / creator"},{"code":"142001","name":"Customer Withholding Tax Receivable","parent":"140000","type":"Asset","normal":"Debit","kind":"Control","subledger":"Customer"},{"code":"150000","name":"Fixed assets","parent":"100000","type":"Asset","normal":"Debit","kind":"Group"},{"code":"151001","name":"Computers and Equipment","parent":"150000","type":"Asset","normal":"Debit","kind":"Posting"},{"code":"152001","name":"Furniture and Fixtures","parent":"150000","type":"Asset","normal":"Debit","kind":"Posting"},{"code":"153001","name":"Vehicles","parent":"150000","type":"Asset","normal":"Debit","kind":"Posting"},{"code":"154001","name":"Leasehold Improvements","parent":"150000","type":"Asset","normal":"Debit","kind":"Posting"},{"code":"159001","name":"Accumulated Depreciation — Computers","parent":"150000","type":"Asset","normal":"Credit","kind":"Posting"},{"code":"159002","name":"Accumulated Depreciation — Furniture","parent":"150000","type":"Asset","normal":"Credit","kind":"Posting"},{"code":"159003","name":"Accumulated Depreciation — Vehicles","parent":"150000","type":"Asset","normal":"Credit","kind":"Posting"},{"code":"159004","name":"Accumulated Depreciation — Leasehold Improvements","parent":"150000","type":"Asset","normal":"Credit","kind":"Posting"},{"code":"200000","name":"Liabilities","parent":null,"type":"Liability","normal":"Credit","kind":"Group"},{"code":"210000","name":"Payables","parent":"200000","type":"Liability","normal":"Credit","kind":"Group"},{"code":"211001","name":"Trade Accounts Payable","parent":"210000","type":"Liability","normal":"Credit","kind":"Control","subledger":"Supplier / creator"},{"code":"212001","name":"Accrued Campaign Costs","parent":"210000","type":"Liability","normal":"Credit","kind":"Posting"},{"code":"213001","name":"Accrued Operating Expenses","parent":"210000","type":"Liability","normal":"Credit","kind":"Posting"},{"code":"220000","name":"Customer advances","parent":"200000","type":"Liability","normal":"Credit","kind":"Group"},{"code":"221001","name":"Customer Advances / Deferred Revenue","parent":"220000","type":"Liability","normal":"Credit","kind":"Control","subledger":"Customer"},{"code":"230000","name":"Taxes payable","parent":"200000","type":"Liability","normal":"Credit","kind":"Group"},{"code":"231001","name":"Output VAT","parent":"230000","type":"Liability","normal":"Credit","kind":"Control","subledger":"Customer"},{"code":"232001","name":"Supplier Withholding Tax Payable","parent":"230000","type":"Liability","normal":"Credit","kind":"Control","subledger":"Supplier / creator"},{"code":"233001","name":"Payroll Tax Payable","parent":"230000","type":"Liability","normal":"Credit","kind":"Posting"},{"code":"234001","name":"Social Insurance Payable","parent":"230000","type":"Liability","normal":"Credit","kind":"Posting"},{"code":"235001","name":"Corporate Income Tax Payable","parent":"230000","type":"Liability","normal":"Credit","kind":"Posting"},{"code":"240000","name":"Other liabilities","parent":"200000","type":"Liability","normal":"Credit","kind":"Group"},{"code":"241001","name":"Salaries Payable","parent":"240000","type":"Liability","normal":"Credit","kind":"Posting"},{"code":"242001","name":"Employee Reimbursements Payable","parent":"240000","type":"Liability","normal":"Credit","kind":"Control","subledger":"Employee"},{"code":"243001","name":"Loans Payable","parent":"240000","type":"Liability","normal":"Credit","kind":"Posting"},{"code":"300000","name":"Equity","parent":null,"type":"Equity","normal":"Credit","kind":"Group"},{"code":"310000","name":"Capital","parent":"300000","type":"Equity","normal":"Credit","kind":"Group"},{"code":"311001","name":"Share Capital","parent":"310000","type":"Equity","normal":"Credit","kind":"Posting"},{"code":"312001","name":"Additional Capital Contributions","parent":"310000","type":"Equity","normal":"Credit","kind":"Posting"},{"code":"320000","name":"Reserves and earnings","parent":"300000","type":"Equity","normal":"Credit","kind":"Group"},{"code":"321001","name":"Retained Earnings","parent":"320000","type":"Equity","normal":"Credit","kind":"Posting"},{"code":"322001","name":"Current-Year Earnings","parent":"320000","type":"Equity","normal":"Credit","kind":"System"},{"code":"323001","name":"Approved Distributions","parent":"320000","type":"Equity","normal":"Debit","kind":"Posting"},{"code":"400000","name":"Revenue","parent":null,"type":"Revenue","normal":"Credit","kind":"Group"},{"code":"410000","name":"Service revenue","parent":"400000","type":"Revenue","normal":"Credit","kind":"Group"},{"code":"411001","name":"Influencer Campaign Revenue","parent":"410000","type":"Revenue","normal":"Credit","kind":"Posting"},{"code":"412001","name":"Media Buying Revenue","parent":"410000","type":"Revenue","normal":"Credit","kind":"Posting"},{"code":"413001","name":"Creative and Production Revenue","parent":"410000","type":"Revenue","normal":"Credit","kind":"Posting"},{"code":"414001","name":"Management and Retainer Fees","parent":"410000","type":"Revenue","normal":"Credit","kind":"Posting"},{"code":"415001","name":"Commission Revenue","parent":"410000","type":"Revenue","normal":"Credit","kind":"Posting"},{"code":"420000","name":"Revenue deductions","parent":"400000","type":"Revenue","normal":"Credit","kind":"Group"},{"code":"421001","name":"Sales Discounts and Allowances","parent":"420000","type":"Revenue","normal":"Debit","kind":"Posting"},{"code":"500000","name":"Direct costs","parent":null,"type":"Expense","normal":"Debit","kind":"Group"},{"code":"510000","name":"Campaign delivery","parent":"500000","type":"Expense","normal":"Debit","kind":"Group"},{"code":"511001","name":"Creator and Influencer Costs","parent":"510000","type":"Expense","normal":"Debit","kind":"Posting"},{"code":"512001","name":"Media Placement Costs","parent":"510000","type":"Expense","normal":"Debit","kind":"Posting"},{"code":"513001","name":"Production Costs","parent":"510000","type":"Expense","normal":"Debit","kind":"Posting"},{"code":"514001","name":"Campaign Freelancers","parent":"510000","type":"Expense","normal":"Debit","kind":"Posting"},{"code":"515001","name":"Campaign Travel and Logistics","parent":"510000","type":"Expense","normal":"Debit","kind":"Posting"},{"code":"600000","name":"Operating expenses","parent":null,"type":"Expense","normal":"Debit","kind":"Group"},{"code":"610000","name":"People costs","parent":"600000","type":"Expense","normal":"Debit","kind":"Group"},{"code":"611001","name":"Salaries","parent":"610000","type":"Expense","normal":"Debit","kind":"Posting"},{"code":"612001","name":"Bonuses and Incentives","parent":"610000","type":"Expense","normal":"Debit","kind":"Posting"},{"code":"613001","name":"Employer Social Insurance","parent":"610000","type":"Expense","normal":"Debit","kind":"Posting"},{"code":"614001","name":"Staff Benefits and Medical Insurance","parent":"610000","type":"Expense","normal":"Debit","kind":"Posting"},{"code":"620000","name":"Office and administration","parent":"600000","type":"Expense","normal":"Debit","kind":"Group"},{"code":"621001","name":"Rent","parent":"620000","type":"Expense","normal":"Debit","kind":"Posting"},{"code":"622001","name":"Utilities and Internet","parent":"620000","type":"Expense","normal":"Debit","kind":"Posting"},{"code":"623001","name":"Software and Subscriptions","parent":"620000","type":"Expense","normal":"Debit","kind":"Posting"},{"code":"624001","name":"Professional and Legal Fees","parent":"620000","type":"Expense","normal":"Debit","kind":"Posting"},{"code":"625001","name":"Office Supplies","parent":"620000","type":"Expense","normal":"Debit","kind":"Posting"},{"code":"626001","name":"Travel and Transportation","parent":"620000","type":"Expense","normal":"Debit","kind":"Posting"},{"code":"630000","name":"Other operating costs","parent":"600000","type":"Expense","normal":"Debit","kind":"Group"},{"code":"631001","name":"Marketing and Business Development","parent":"630000","type":"Expense","normal":"Debit","kind":"Posting"},{"code":"632001","name":"Bank Charges","parent":"630000","type":"Expense","normal":"Debit","kind":"Posting"},{"code":"633000","name":"Depreciation expenses","parent":"630000","type":"Expense","normal":"Debit","kind":"Group"},{"code":"633001","name":"Depreciation — Computers and Equipment","parent":"633000","type":"Expense","normal":"Debit","kind":"Posting"},{"code":"633002","name":"Depreciation — Furniture and Fixtures","parent":"633000","type":"Expense","normal":"Debit","kind":"Posting"},{"code":"633003","name":"Depreciation — Vehicles","parent":"633000","type":"Expense","normal":"Debit","kind":"Posting"},{"code":"633004","name":"Depreciation — Leasehold Improvements","parent":"633000","type":"Expense","normal":"Debit","kind":"Posting"},{"code":"634001","name":"Credit Loss Expense","parent":"630000","type":"Expense","normal":"Debit","kind":"Posting"},{"code":"700000","name":"Other income and expenses","parent":null,"type":"Expense","normal":"Debit","kind":"Group"},{"code":"710000","name":"Other income","parent":"700000","type":"Revenue","normal":"Credit","kind":"Group"},{"code":"711001","name":"Interest Income","parent":"710000","type":"Revenue","normal":"Credit","kind":"Posting"},{"code":"712001","name":"Realized Foreign Exchange Gains","parent":"710000","type":"Revenue","normal":"Credit","kind":"Posting"},{"code":"713001","name":"Unrealized Foreign Exchange Gains","parent":"710000","type":"Revenue","normal":"Credit","kind":"Posting"},{"code":"720000","name":"Other expenses","parent":"700000","type":"Expense","normal":"Debit","kind":"Group"},{"code":"721001","name":"Interest Expense","parent":"720000","type":"Expense","normal":"Debit","kind":"Posting"},{"code":"722001","name":"Realized Foreign Exchange Losses","parent":"720000","type":"Expense","normal":"Debit","kind":"Posting"},{"code":"723001","name":"Unrealized Foreign Exchange Losses","parent":"720000","type":"Expense","normal":"Debit","kind":"Posting"},{"code":"800000","name":"Income tax","parent":null,"type":"Expense","normal":"Debit","kind":"Group"},{"code":"810000","name":"Income tax expense","parent":"800000","type":"Expense","normal":"Debit","kind":"Group"},{"code":"811001","name":"Income Tax Expense","parent":"810000","type":"Expense","normal":"Debit","kind":"Posting"}]');
 RESET ROLE;
 SELECT * INTO STRICT l FROM campaign_lines WHERE NOT cost_locked AND vendor_io_id IS NULL AND EXISTS(SELECT 1 FROM campaign_influencers WHERE campaign_line_id=campaign_lines.id) LIMIT 1;
 SELECT * INTO STRICT a FROM campaign_influencers WHERE campaign_line_id=l.id LIMIT 1;
 l:=jsonb_populate_record(l,jsonb_build_object('id',gen_random_uuid(),'document_number','QA-ACCRUAL-'||inv,'name','Isolated accrual fixture','invoice_id',NULL,'vendor_io_id',NULL,'cost_locked',false,'revenue_locked',false,'vat_locked',false,'vendor_assignment_locked',false,'cost',600,'cost_before_vat',600,'cost_received',600,'cost_received_currency','EGP','usage_rights_cost',0,'currency_code','EGP','cost_vat_percent',0,'cost_vat_exempt',true,'fx_rate',1,'fx_cost_revenue_cross_rate',NULL,'pricing_mode','package','metadata','{}'::jsonb));
 INSERT INTO campaign_lines SELECT l.*;
 a:=jsonb_populate_record(a,jsonb_build_object('id',gen_random_uuid(),'campaign_line_id',l.id,'agreed_fee',600,'cost_before_vat',600,'cost_after_vat',600,'vendor_payment_status','unpaid'));
 INSERT INTO campaign_influencers SELECT a.*;
 SET LOCAL ROLE authenticated;
 r:=tw_accounting_create_client(c,'QA queue client '||inv,'QA queue client '||inv,'direct','EGP','EG');client:=(r->>'id')::uuid;
 PERFORM tw_accounting_mapping_save(c,'assignment_cost','511001',NULL,0);
 PERFORM tw_accounting_mapping_save(c,'accrued_cost','212001',NULL,0);
 RESET ROLE;
 INSERT INTO invoices(id,document_number,client_id,issue_date,currency,subtotal,tax_amount,total,revenue_before_vat,revenue_vat_amount,revenue_after_vat) VALUES(inv,'QA-QUEUE-'||inv,client,'2026-01-15','EGP',1000,140,1140,1000,140,1140);
 INSERT INTO invoice_line_items(invoice_id,sort_order,description,quantity,unit_price,revenue_before_vat,revenue_vat_percent,campaign_line_id,metadata) VALUES(inv,1,'Accrual test',1,1000,1000,14,l.id,'{"accounting_components":{"assignment_revenue":1000,"usage_rights_revenue":0,"agency_fee":0},"operational_source_amount":1000}');
 UPDATE invoices SET amounts_finalized_at=now() WHERE id=inv;
 SET LOCAL ROLE authenticated;
 q:=tw_accounting_media_source(c,'client_invoice',inv);
 IF q->'accruals'<>'[]'::jsonb THEN RAISE EXCEPTION 'Accrual default is not off';END IF;
 SELECT version INTO v FROM tw_accounting_companies WHERE id=c;PERFORM tw_accounting_accrual_setting(c,true,v);
 q:=tw_accounting_media_source(c,'client_invoice',inv);
 j:=tw_accounting_media_post(c,'client_invoice',inv,q->>'token');
 IF (SELECT entry_date<>(now() AT TIME ZONE 'Africa/Cairo')::date OR activation_date<>'2026-01-15'::date FROM tw_accounting_journals WHERE id=j) THEN RAISE EXCEPTION 'Invoice dates wrong';END IF;
 IF tw_accounting_media_post(c,'client_invoice',inv,q->>'token')<>j THEN RAISE EXCEPTION 'Duplicate invoice JV';END IF;
 IF (SELECT sum(amount) FROM tw_accounting_cost_accruals WHERE invoice_id=inv)<>600 THEN RAISE EXCEPTION 'Net accrual wrong';END IF;
 IF (SELECT sum(credit) FROM tw_accounting_journal_lines WHERE journal_id=j AND account_code='231001')<>140 THEN RAISE EXCEPTION 'VAT was accrued or lost';END IF;
 RESET ROLE;
 INSERT INTO creator_supplier_invoices(id,request_id,assignment_id,status,invoice_number,invoice_date,country_code,currency,supplier_name,subtotal,vat_amount,confirmed,recorded_by) VALUES(supplier,gen_random_uuid(),a.id,'received','QA-SUP-'||supplier,'2026-01-16','EG','EGP','Isolated cost',200,28,true,actor);
 SET LOCAL ROLE authenticated;
 q:=tw_accounting_media_source(c,'supplier_invoice',supplier);j2:=tw_accounting_media_post(c,'supplier_invoice',supplier,q->>'token');
 IF (SELECT entry_date<>(now() AT TIME ZONE 'Africa/Cairo')::date OR activation_date<>'2026-01-16'::date FROM tw_accounting_journals WHERE id=j2) THEN RAISE EXCEPTION 'Cost dates wrong';END IF;
 IF (SELECT sum(amount) FROM tw_accounting_accrual_clearings WHERE journal_id=j2)<>200 THEN RAISE EXCEPTION 'Partial clearing must exclude 28 VAT';END IF;
 IF (SELECT sum(credit-debit) FROM tw_accounting_journal_lines WHERE company_id=c AND account_code='212001')<>400 THEN RAISE EXCEPTION 'Remaining accrual wrong';END IF;
 q:=tw_accounting_media_source(c,'client_invoice',inv);blocked:=false;BEGIN PERFORM tw_accounting_media_unpost(c,'client_invoice',inv,(q->>'version')::integer,'Blocked linked cost');EXCEPTION WHEN raise_exception THEN blocked:=true;END;IF NOT blocked THEN RAISE EXCEPTION 'Consumed accrual unposted';END IF;
 SELECT voucher_number INTO serial FROM tw_accounting_journals WHERE id=j2;
 q:=tw_accounting_media_source(c,'supplier_invoice',supplier);PERFORM tw_accounting_media_unpost(c,'supplier_invoice',supplier,(q->>'version')::integer,'Test correction');
 IF (SELECT status FROM tw_accounting_journals WHERE id=j2)<>'pending' THEN RAISE EXCEPTION 'Unpost did not set pending';END IF;
 RESET ROLE;UPDATE creator_supplier_invoices SET subtotal=300,vat_amount=42 WHERE id=supplier;SET LOCAL ROLE authenticated;
 q:=tw_accounting_media_source(c,'supplier_invoice',supplier);IF tw_accounting_media_post(c,'supplier_invoice',supplier,q->>'token')<>j2 OR (SELECT voucher_number FROM tw_accounting_journals WHERE id=j2)<>serial THEN RAISE EXCEPTION 'Reposting duplicated JV or serial';END IF;
 IF (SELECT sum(amount) FROM tw_accounting_accrual_clearings WHERE journal_id=j2)<>300 THEN RAISE EXCEPTION 'Repost did not revise partial clearing';END IF;
 -- Internal cost to actual supplier invoice: reverse original 100, book 120
 -- plus 16.80 VAT, and clear only the extra 20 of net accrual.
 cost:=gen_random_uuid();
 PERFORM tw_accounting_cost_save(jsonb_build_object('id',cost,'company',c,'version',NULL,'vendor',a.influencer_id,'assignment',l.id,'date','2026-01-17','due','','currency','EGP','net','100','tax','0','expense','511001','payable','211001','vat','141001','description','Internal accrual clearance','reference','QA provisional','supplierNumber','','supplierDate',''));
 q:=tw_accounting_media_source(c,'internal_cost',cost);PERFORM tw_accounting_media_post(c,'internal_cost',cost,q->>'token');
 j:=tw_accounting_post_with_aux('cost-reconcile',jsonb_build_object('id',cost,'company',c,'version',2,'date',(now() AT TIME ZONE 'Africa/Cairo')::date::text,'number','QA-ACTUAL','supplierDate','2026-01-18','net','120','tax','16.80','vat','141001','reference','QA actual supplier invoice'));
 IF NOT EXISTS(SELECT 1 FROM tw_accounting_journal_lines WHERE journal_id=j AND description LIKE 'Reverse original cost:%' AND credit=100) OR NOT EXISTS(SELECT 1 FROM tw_accounting_journal_lines WHERE journal_id=j AND description LIKE 'Actual supplier cost:%' AND debit=120) OR NOT EXISTS(SELECT 1 FROM tw_accounting_journal_lines WHERE journal_id=j AND account_code='141001' AND debit=16.8) THEN RAISE EXCEPTION 'Actual cost replacement did not reverse original and recognise full new cost with VAT';END IF;
 IF (SELECT sum(amount) FROM tw_accounting_accrual_clearings WHERE cost_id=cost)<>120 THEN RAISE EXCEPTION 'Actual supplier invoice clearing includes VAT or ignores delta';END IF;
 q:=tw_accounting_media_queue(c,'client_invoice','2026-01-01','2026-12-31',true,0);
 IF NOT EXISTS(SELECT 1 FROM jsonb_array_elements(q->'rows') x WHERE x->>'id'=inv::text) THEN RAISE EXCEPTION 'Posted invoice missing from queue';END IF;
 q:=tw_accounting_media_queue(c,'client_invoice','2026-01-01','2026-12-31',false,0);
 IF EXISTS(SELECT 1 FROM jsonb_array_elements(q->'rows') x WHERE x->>'id'=inv::text) THEN RAISE EXCEPTION 'Posted invoice remains unposted';END IF;
 FOREACH k IN ARRAY ARRAY['client_credit_note','client_debit_note','vendor_credit_note','vendor_debit_note'] LOOP
  note:=gen_random_uuid();t:=k||'s';RESET ROLE;
  IF k LIKE 'client_%' THEN EXECUTE format('INSERT INTO %I(id,document_number,status,invoice_id,client_id,issue_date,reason,amount_before_vat,vat_amount,amount_after_vat,currency,created_by) VALUES($1,$2,''approved'',$3,$4,''2026-01-17'',''Isolated note'',10,1.4,11.4,''EGP'',$5)',t) USING note,'QA-'||note,inv,client,actor;
  ELSE EXECUTE format('INSERT INTO %I(id,document_number,status,vendor_id,issue_date,reason,amount_before_vat,vat_amount,amount_after_vat,currency,created_by) VALUES($1,$2,''approved'',$3,''2026-01-17'',''Isolated note'',10,1.4,11.4,''EGP'',$4)',t) USING note,'QA-'||note,a.influencer_id,actor;END IF;
  SET LOCAL ROLE authenticated;q:=tw_accounting_media_source(c,k,note);j:=tw_accounting_media_post(c,k,note,q->>'token');
  IF tw_accounting_media_post(c,k,note,q->>'token')<>j THEN RAISE EXCEPTION 'Duplicate note JV';END IF;

  target:=CASE WHEN k LIKE 'client_%' THEN inv ELSE (SELECT cost_id FROM tw_accounting_media_postings WHERE source_id=supplier AND source_type='supplier_invoice') END;
  sgn:=CASE WHEN k LIKE '%credit_note' THEN -1 ELSE 1 END;
  r:=tw_accounting_note_allocation_read(c,k,note);
  SELECT (x->>'outstanding')::numeric INTO before_balance FROM jsonb_array_elements(r->'invoices')x WHERE x->>'id'=target::text;
  IF before_balance IS NULL THEN RAISE EXCEPTION 'Related invoice missing from picker';END IF;
  q:=tw_accounting_media_source(c,k,note);
  PERFORM tw_accounting_note_allocate(c,k,note,(q->>'version')::integer,jsonb_build_array(jsonb_build_object('id',target,'amount','5.70')));
  r:=tw_accounting_note_allocation_read(c,k,note);
  IF NOT EXISTS(SELECT 1 FROM jsonb_array_elements(r->'invoices')x WHERE x->>'id'=target::text AND (x->>'outstanding')::numeric=before_balance+sgn*5.7) THEN RAISE EXCEPTION 'Partial allocation outstanding incorrect';END IF;
  q:=tw_accounting_aging(c,CASE WHEN k LIKE 'client_%' THEN 'client' ELSE 'vendor' END,'EGP',CASE WHEN k LIKE 'client_%' THEN client ELSE a.influencer_id END);
  IF NOT EXISTS(SELECT 1 FROM jsonb_array_elements(q)x WHERE x->>'id'=note::text AND (x->>'outstanding')::numeric=sgn*5.7) THEN RAISE EXCEPTION 'Aging residual note incorrect';END IF;

  q:=tw_accounting_media_source(c,k,note);
  PERFORM set_config('request.jwt.claims',jsonb_build_object('sub',actor,'role','authenticated','aal','aal1')::text,true);blocked:=false;
  BEGIN PERFORM tw_accounting_note_allocate(c,k,note,(q->>'version')::integer,'[]');EXCEPTION WHEN insufficient_privilege THEN blocked:=true;END;
  PERFORM set_config('request.jwt.claims',jsonb_build_object('sub',actor,'role','authenticated','aal','aal2')::text,true);
  IF NOT blocked THEN RAISE EXCEPTION 'Allocation bypassed MFA';END IF;
  SELECT version INTO v FROM tw_accounting_journals WHERE id=j;PERFORM tw_accounting_control_action(c,'lock',jsonb_build_array(jsonb_build_object('id',j,'version',v)),'QA note lock');blocked:=false;
  BEGIN PERFORM tw_accounting_note_allocate(c,k,note,(q->>'version')::integer,'[]');EXCEPTION WHEN raise_exception THEN blocked:=true;END;
  IF NOT blocked THEN RAISE EXCEPTION 'Allocation changed locked note';END IF;
  SELECT version INTO v FROM tw_accounting_journals WHERE id=j;PERFORM tw_accounting_control_action(c,'unlock',jsonb_build_array(jsonb_build_object('id',j,'version',v)),'QA note unlock');
  q:=tw_accounting_media_source(c,k,note);blocked:=false;
  BEGIN PERFORM tw_accounting_note_allocate(c,k,note,(q->>'version')::integer,jsonb_build_array(jsonb_build_object('id',target,'amount','12.00')));EXCEPTION WHEN raise_exception THEN blocked:=true;END;
  IF NOT blocked THEN RAISE EXCEPTION 'Note over-allocation accepted';END IF;
  blocked:=false;BEGIN PERFORM tw_accounting_media_unpost(c,k,note,(q->>'version')::integer,'Has allocations');EXCEPTION WHEN raise_exception THEN blocked:=true;END;
  IF NOT blocked THEN RAISE EXCEPTION 'Allocated note unposted';END IF;
  PERFORM tw_accounting_note_allocate(c,k,note,(q->>'version')::integer,jsonb_build_array(jsonb_build_object('id',target,'amount','11.40')));
  q:=tw_accounting_aging(c,CASE WHEN k LIKE 'client_%' THEN 'client' ELSE 'vendor' END,'EGP',CASE WHEN k LIKE 'client_%' THEN client ELSE a.influencer_id END);
  IF EXISTS(SELECT 1 FROM jsonb_array_elements(q)x WHERE x->>'id'=note::text) THEN RAISE EXCEPTION 'Fully allocated note double counted in aging';END IF;
  IF NOT EXISTS(SELECT 1 FROM jsonb_array_elements(q)x WHERE x->>'id'=target::text AND (x->>'outstanding')::numeric=before_balance+sgn*11.4) THEN RAISE EXCEPTION 'Invoice aging incorrect';END IF;

  cash_id:=gen_random_uuid();
  cash_value:=jsonb_build_object('company',c,'party',CASE WHEN k LIKE 'client_%' THEN client ELSE a.influencer_id END,'kind',CASE WHEN k LIKE 'client_%' THEN 'receipt' ELSE 'payment' END,'date',(now() AT TIME ZONE 'Africa/Cairo')::date::text,'currency','EGP','amount',(before_balance+sgn*11.4)::text,'control',CASE WHEN k LIKE 'client_%' THEN '121001' ELSE '211001' END,'advance',CASE WHEN k LIKE 'client_%' THEN '221001' ELSE '131001' END,'cash','112001','gain','712001','loss','722001','method','bank_transfer','reference','QA note settlement','lines',jsonb_build_array(jsonb_build_object('id',target,'amount',(before_balance+sgn*11.4)::text)));
